@[simp]
theorem splittings_zero (D : EffectiveCurveMonoid B) :
    D.splittings 0 = {(0, 0)}

@[ext]
theorem ext {f g : NovikovSeries D R}
    (h : ∀ beta : B, coeff D beta f = coeff D beta g) : f = g

@[ext]
theorem ext {F G : CompletedFockPotential D Vars R}
    (h : ∀ n, F.coefficient n = G.coefficient n) : F = G
